  bayTobiano:    "https://media.base44.com/images/public/69b44c69482b4d9133223b0e/f74c2c196_generated_image.png",
  chestnutTobiano: "https://media.base44.com/images/public/69b44c69482b4d9133223b0e/ffceff460_generated_image.png",
